const config = {
  "previewFeatures": [],
  "clientVersion": "7.10.0",
  "engineVersion": "0edf323efd1d98336f3f0a68684b56f689b900d3",
  "activeProvider": "sqlite",
  "inlineSchema": "// AUTO-GENERATED from schema.prisma by scripts/gen-sqlite-schema.mjs — do not edit.\ngenerator client {\n  provider = \"prisma-client-js\"\n  output   = \"../src/generated/prisma-sqlite\"\n}\n\n// Prisma 7: url lives in prisma.config.ts (PostgreSQL).\n// Offline desktop uses prisma/schema.sqlite.prisma (generated, git-ignored).\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// ─── Auth / tenancy ──────────────────────────────────────────────────────────\n\nmodel Company {\n  id           String   @id @default(cuid())\n  name         String\n  phone        String?\n  address      String?\n  email        String?\n  /// Algerian fiscal IDs (shown on invoices / sheets).\n  rc           String?\n  nif          String?\n  ai           String?\n  nis          String?\n  bankName     String?\n  rib          String?\n  logoUrl      String?\n  /// Signature + stamp images printed on documents.\n  signatureUrl String?\n  stampUrl     String?\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  users            User[]\n  stores           Store[]\n  customers        Customer[]\n  suppliers        Supplier[]\n  products         Product[]\n  seasons          Season[]\n  settings         CompanySettings?\n  units            Unit[]\n  priceTiers       PriceTier[]\n  expenseTypes     ExpenseType[]\n  secteurs         Secteur[]\n  purchaseInvoices PurchaseInvoice[]\n  supplierReturns  SupplierReturn[]\n  stockBatches     StockBatch[]\n  transfers        Transfer[]\n  stockCounts      StockCount[]\n  stockLosses      StockLoss[]\n  sales            Sale[]\n  threePackRules   ThreePackRule[]\n  clientReturns    ClientReturn[]\n  closedVisits     ClosedVisit[]\n  tournees         Tournee[]\n  tourneePlans     TourneePlan[]\n  expenses         Expense[]\n  versements       Versement[]\n  distances        ClientDistance[]\n  deposits         Deposit[]\n  devices          Device[]\n  syncOps          SyncOp[]\n  dailyCloses      DailyClose[]\n\n  @@map(\"companies\")\n}\n\nmodel CompanySettings {\n  id            String  @id @default(cuid())\n  companyId     String  @unique\n  company       Company @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  defaultLocale String  @default(\"ar\")\n  currency      String  @default(\"DZD\")\n\n  // ── Feature toggles (every toggle gates real logic + UI + reports) ──\n  expiryEnabled           Boolean   @default(false)\n  creditSalesEnabled      Boolean   @default(false)\n  debtTrackingEnabled     Boolean   @default(true)\n  remiseEnabled           Boolean   @default(false)\n  depositsEnabled         Boolean   @default(false)\n  multiDepotEnabled       Boolean   @default(false)\n  costingMethod           String    @default(\"FIFO\")\n  facturePro              Boolean   @default(false)\n  posEnabled              Boolean   @default(false)\n  vanBindingMode          String    @default(\"LOCKED\")\n  oversellAllowed         Boolean   @default(true)\n  pieceSalesEnabled       Boolean   @default(false)\n  /// Transfers need an explicit receipt confirmation (declare → confirm).\n  /// OFF = declare delivers straight to destination (single-step).\n  transferConfirmRequired Boolean   @default(true)\n  gpsEnabled              Boolean   @default(true)\n  qrStrictMode            Boolean   @default(true)\n  /// Thermal ticket paper width in mm (admin setting: \"58\" or \"80\").\n  ticketWidth             String    @default(\"80\")\n  /// Thermal ticket language (admin setting: \"ar\" or \"fr\", default French).\n  ticketLang              String    @default(\"fr\")\n  /// Purchase picker: only the chosen supplier's products (default ON).\n  supplierFilterEnabled   Boolean   @default(true)\n  /// 3pack: free-colis bonus rules (buy X get Y free). Admin-editable.\n  threePackEnabled        Boolean   @default(false)\n  /// Expected départ time for vans (\"HH:MM\", null = no late flag).\n  workStartAt             String?\n  /// A journée longer than this (hours) flags overtime on presence.\n  maxDayHours             Float?    @default(10)\n  /// Public internet domain for this install's phones\n  /// (e.g. client1.distribuili.khiatadz.com, no scheme). The Devices setup QR\n  /// uses it when set, so vans reach the PC through the tunnel from anywhere.\n  remoteDomain            String?\n  /// One-time conversion of the old copy-forward tours into endless plans.\n  tourPlansMigratedAt     DateTime?\n\n  @@map(\"company_settings\")\n}\n\n// ─── Settings-managed reference lists ────────────────────────────────────────\n\nmodel Unit {\n  id        String   @id @default(cuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  name      String\n  symbol    String?\n  sortOrder Int      @default(0)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  baseFor     Product[]               @relation(\"BaseUnit\")\n  saleFor     Product[]               @relation(\"SaleUnit\")\n  purchaseFor Product[]               @relation(\"PurchaseUnit\")\n  conversions ProductUnitConversion[]\n\n  @@unique([companyId, name])\n  @@map(\"units\")\n}\n\nmodel PriceTier {\n  id        String   @id @default(cuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  name      String\n  sortOrder Int      @default(0)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  prices    ProductTierPrice[]\n  customers Customer[]\n  sales     Sale[]\n\n  @@unique([companyId, name])\n  @@map(\"price_tiers\")\n}\n\nmodel ExpenseType {\n  id        String   @id @default(cuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  name      String\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n\n  expenses Expense[]\n\n  @@unique([companyId, name])\n  @@map(\"expense_types\")\n}\n\n/// National reference: 58 wilayas (global, seeded once — not per company).\nmodel Wilaya {\n  code   Int    @id\n  nameFr String\n  nameAr String\n\n  secteurs  Secteur[]\n  customers Customer[]\n  suppliers Supplier[]\n  userAreas UserArea[]\n}\n\n/// Secteur inside a wilaya, per company (dispatch + tournées operate on these).\nmodel Secteur {\n  id         String   @id @default(cuid())\n  companyId  String\n  company    Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  wilayaCode Int\n  wilaya     Wilaya   @relation(fields: [wilayaCode], references: [code], onDelete: Restrict)\n  name       String\n  isActive   Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  customers    Customer[]\n  suppliers    Supplier[]\n  tournees     Tournee[]\n  tourneePlans TourneePlan[]\n  userAreas    UserArea[]\n\n  @@unique([companyId, wilayaCode, name])\n  @@index([companyId, wilayaCode])\n  @@map(\"secteurs\")\n}\n\nmodel User {\n  id           String   @id @default(cuid())\n  companyId    String\n  company      Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  username     String\n  passwordHash String\n  /// Staff phone number (login accepts username OR phone).\n  phone        String?\n  /// Admin-visible copy of the password (staff QR cards). Auth still uses\n  /// bcrypt passwordHash; this column exists only so the admin can read it\n  /// back on the Livreur / Pré-vendeur cards.\n  passwordView String?\n  /// Long-lived staff login token (QR cards + scan-to-login). Revocable via\n  /// regenerate. Stored raw so cards can re-render the QR at any time.\n  qrToken      String?  @unique\n  fullName     String\n  role         String   @default(\"Vendeur\")\n  isActive     Boolean  @default(true)\n  /// Livreur / Vendeur may pick the journée day. false (default) = locked to\n  /// today's tour only (admin toggles it in Settings > day access).\n  canChooseDay Boolean  @default(false)\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  distances ClientDistance[]\n  areas     UserArea[]\n\n  assignedVans Store[]       @relation(\"AssignedVan\")\n  devices      Device[]\n  closedVisits ClosedVisit[]\n  createdSales Sale[]        @relation(\"CreatedSales\")\n\n  @@unique([companyId, username])\n  @@map(\"users\")\n}\n\n/// Zones a Livreur / Pré-vendeur may create clients in (admin-assigned).\n/// No rows for a user = unrestricted (sees every wilaya and secteur).\n/// secteurId null = the whole wilaya; otherwise that single secteur only.\nmodel UserArea {\n  id         String   @id @default(cuid())\n  userId     String\n  user       User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  wilayaCode Int\n  wilaya     Wilaya   @relation(fields: [wilayaCode], references: [code], onDelete: Cascade)\n  secteurId  String?\n  secteur    Secteur? @relation(fields: [secteurId], references: [id], onDelete: Cascade)\n  createdAt  DateTime @default(now())\n\n  @@index([userId])\n  @@map(\"user_areas\")\n}\n\nmodel RefreshToken {\n  id        String   @id @default(cuid())\n  userId    String\n  tokenHash String   @unique\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  @@index([userId])\n  @@map(\"refresh_tokens\")\n}\n\nmodel SuperAdminUser {\n  id                String    @id @default(cuid())\n  username          String    @unique\n  passwordHash      String\n  isActive          Boolean   @default(true)\n  passwordChangedAt DateTime?\n  createdAt         DateTime  @default(now())\n\n  audits SuperAdminAudit[]\n\n  @@map(\"super_admin_users\")\n}\n\n/// Every superadmin action (who did what to which machine/key, when, from where).\nmodel SuperAdminAudit {\n  id         String         @id @default(cuid())\n  adminId    String\n  admin      SuperAdminUser @relation(fields: [adminId], references: [id], onDelete: Cascade)\n  action     String\n  targetType String?\n  targetId   String?\n  meta       Json?\n  ip         String?\n  createdAt  DateTime       @default(now())\n\n  @@index([adminId, createdAt])\n  @@map(\"super_admin_audits\")\n}\n\n// ─── Distribution domain (minimal foundation) ────────────────────────────────\n\nmodel Store {\n  id                String    @id @default(cuid())\n  companyId         String\n  company           Company   @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  name              String\n  address           String?\n  /// DEPOT = fixed warehouse, VAN = van stock (marque + matricule).\n  kind              String    @default(\"DEPOT\")\n  marque            String?\n  matricule         String?\n  /// Van photo (uploads/vans/…). Null = placeholder icon.\n  imageUrl          String?\n  userId            String?\n  user              User?     @relation(\"AssignedVan\", fields: [userId], references: [id], onDelete: SetNull)\n  isActive          Boolean   @default(true)\n  /// Live GPS tracking (APK reports via POST /api/track).\n  lastLat           Float?\n  lastLng           Float?\n  lastSeenAt        DateTime?\n  /// Admin pressed \"request location\" (POST /api/vans/[id]/locate).\n  /// The APK polls it and reports immediately; cleared on next report.\n  locateRequestedAt DateTime?\n  /// Per-van QR rules (Settings → QR): must the driver scan the client QR\n  /// to sell / to create an order.\n  qrSellRequired    Boolean   @default(true)\n  qrOrderRequired   Boolean   @default(true)\n  createdAt         DateTime  @default(now())\n  updatedAt         DateTime  @updatedAt\n\n  batches       StockBatch[]\n  transfersFrom Transfer[]     @relation(\"TransferFrom\")\n  transfersTo   Transfer[]     @relation(\"TransferTo\")\n  counts        StockCount[]\n  losses        StockLoss[]\n  sales         Sale[]\n  clientReturns ClientReturn[]\n  closedVisits  ClosedVisit[]\n  tournees      Tournee[]\n  tourneePlans  TourneePlan[]\n  expenseLinks  Expense[]\n  devices       Device[]\n  dailyCloses   DailyClose[]\n\n  /// One driver ↔ max one van (NULL userIds are always allowed).\n  @@unique([companyId, userId])\n  @@map(\"stores\")\n}\n\n/// Declare → confirm transfer (depot↔van, van↔van, depot↔depot).\n/// Stock leaves the source at declare (in-transit holding batches),\n/// enters the destination only at confirm. Nothing moves silently.\nmodel Transfer {\n  id             String   @id @default(cuid())\n  companyId      String\n  company        Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId       String?\n  number         String\n  fromLocationId String\n  fromLocation   Store    @relation(\"TransferFrom\", fields: [fromLocationId], references: [id], onDelete: Restrict)\n  toLocationId   String\n  toLocation     Store    @relation(\"TransferTo\", fields: [toLocationId], references: [id], onDelete: Restrict)\n  status         String   @default(\"DECLARED\")\n  /// Cash the vendeur hands over with a van→depot return (versement link in Phase 6).\n  cashAmount     Decimal  @default(0)\n  notes          String?\n  declaredById   String?\n  confirmedById  String?\n  date           DateTime @default(now())\n  createdAt      DateTime @default(now())\n  updatedAt      DateTime @updatedAt\n\n  lines          TransferLine[]\n  holdingBatches StockBatch[]   @relation(\"HoldingBatches\")\n  versements     Versement[]\n\n  /// Offline idempotency key: the sync opId that declared this transfer.\n  opId String?\n\n  @@unique([companyId, number])\n  @@unique([companyId, opId])\n  @@index([companyId, status])\n  @@map(\"transfers\")\n}\n\nmodel TransferLine {\n  id           String   @id @default(cuid())\n  transferId   String\n  transfer     Transfer @relation(fields: [transferId], references: [id], onDelete: Cascade)\n  productId    String\n  product      Product  @relation(fields: [productId], references: [id], onDelete: Restrict)\n  declaredQty  Decimal\n  confirmedQty Decimal?\n\n  @@index([transferId])\n  @@map(\"transfer_lines\")\n}\n\n/// Physical stock count per location, then validated into adjustments.\n\nmodel StockCount {\n  id         String   @id @default(cuid())\n  companyId  String\n  company    Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId   String?\n  locationId String\n  location   Store    @relation(fields: [locationId], references: [id], onDelete: Restrict)\n  number     String\n  status     String   @default(\"DRAFT\")\n  notes      String?\n  date       DateTime @default(now())\n  createdAt  DateTime @default(now())\n\n  lines StockCountLine[]\n\n  @@unique([companyId, number])\n  @@index([companyId, locationId])\n  @@map(\"stock_counts\")\n}\n\nmodel StockCountLine {\n  id          String     @id @default(cuid())\n  countId     String\n  count       StockCount @relation(fields: [countId], references: [id], onDelete: Cascade)\n  productId   String\n  product     Product    @relation(fields: [productId], references: [id], onDelete: Restrict)\n  expectedQty Decimal\n  countedQty  Decimal\n\n  @@index([countId])\n  @@map(\"stock_count_lines\")\n}\n\n/// Breakage / loss / gift recording (consumes FIFO, decrements stock).\nmodel StockLoss {\n  id         String   @id @default(cuid())\n  companyId  String\n  company    Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId   String?\n  locationId String\n  location   Store    @relation(fields: [locationId], references: [id], onDelete: Restrict)\n  productId  String\n  product    Product  @relation(fields: [productId], references: [id], onDelete: Restrict)\n  baseQty    Decimal\n  motive     String\n  notes      String?\n  date       DateTime @default(now())\n  createdAt  DateTime @default(now())\n\n  @@index([companyId, locationId])\n  @@map(\"stock_losses\")\n}\n\n/// Monthly accounting period, auto-created (never manual, never deletable).\n\nmodel Season {\n  id        String   @id @default(cuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  year      Int\n  month     Int\n  status    String   @default(\"open\")\n  createdAt DateTime @default(now())\n\n  @@unique([companyId, year, month])\n  @@map(\"seasons\")\n}\n\nmodel Customer {\n  id               String     @id @default(cuid())\n  companyId        String\n  company          Company    @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  /// Stable code: QR payload + printed cards (`CLT-0001…`).\n  code             String\n  legacyQr         String?\n  name             String\n  /// Portal username (unique per company).\n  phone            String?\n  address          String?\n  wilayaCode       Int?\n  wilaya           Wilaya?    @relation(fields: [wilayaCode], references: [code], onDelete: SetNull)\n  secteurId        String?\n  secteur          Secteur?   @relation(fields: [secteurId], references: [id], onDelete: SetNull)\n  activityType     String?\n  /// Optional fiscal identifiers (prefill the Bon de route / facture).\n  rc               String?\n  ai               String?\n  nif              String?\n  nis              String?\n  rib              String?\n  /// Sale price tier assigned at creation.\n  tierId           String?\n  tier             PriceTier? @relation(fields: [tierId], references: [id], onDelete: SetNull)\n  creditLimit      Decimal    @default(0)\n  creditDays       Int        @default(0)\n  gpsLat           Float?\n  gpsLng           Float?\n  /// Bcrypt hash of the portal secret code (login = phone + secret).\n  portalSecretHash String?\n  balance          Decimal    @default(0)\n  isActive         Boolean    @default(true)\n  createdAt        DateTime   @default(now())\n  updatedAt        DateTime   @updatedAt\n\n  /// Offline idempotency key: the sync opId that created this client.\n  opId String?\n\n  distances    ClientDistance[]\n  closedVisits ClosedVisit[]\n\n  sales        Sale[]\n  returns      ClientReturn[]\n  tourneeStops TourneeStop[]\n  versements   Versement[]\n  deposits     Deposit[]\n\n  @@unique([companyId, code])\n  @@unique([companyId, legacyQr])\n  @@unique([companyId, phone])\n  @@unique([companyId, opId])\n  @@index([companyId, name])\n  @@index([companyId, secteurId])\n  @@map(\"customers\")\n}\n\nmodel Supplier {\n  id        String   @id @default(cuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  name      String\n  phone     String?\n  address   String?\n  balance   Decimal  @default(0)\n  isActive  Boolean  @default(true)\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  code             String?\n  wilayaCode       Int?\n  wilaya           Wilaya?           @relation(fields: [wilayaCode], references: [code], onDelete: SetNull)\n  secteurId        String?\n  secteur          Secteur?          @relation(fields: [secteurId], references: [id], onDelete: SetNull)\n  notes            String?\n  defaultProducts  Product[]         @relation(\"DefaultSupplier\")\n  purchaseInvoices PurchaseInvoice[]\n  supplierReturns  SupplierReturn[]\n  versements       Versement[]\n\n  @@unique([companyId, code])\n  @@index([companyId, name])\n  @@map(\"suppliers\")\n}\n\nmodel ProductCategory {\n  id        String    @id @default(cuid())\n  companyId String\n  name      String\n  createdAt DateTime  @default(now())\n  products  Product[]\n\n  @@unique([companyId, name])\n  @@map(\"product_categories\")\n}\n\nmodel Product {\n  id             String           @id @default(cuid())\n  companyId      String\n  company        Company          @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  categoryId     String?\n  category       ProductCategory? @relation(fields: [categoryId], references: [id], onDelete: SetNull)\n  supplierId     String?\n  supplier       Supplier?        @relation(\"DefaultSupplier\", fields: [supplierId], references: [id], onDelete: SetNull)\n  name           String\n  reference      String?\n  barcode        String?\n  /// Colisage: free text, e.g. \"12 pcs/ctn\".\n  colisage       String?\n  baseUnitId     String?\n  baseUnit       Unit?            @relation(\"BaseUnit\", fields: [baseUnitId], references: [id], onDelete: SetNull)\n  /// Grossiste packaging: default unit used when buying / selling.\n  /// Must be the base unit or one of this product's conversions.\n  saleUnitId     String?\n  saleUnit       Unit?            @relation(\"SaleUnit\", fields: [saleUnitId], references: [id], onDelete: SetNull)\n  purchaseUnitId String?\n  purchaseUnit   Unit?            @relation(\"PurchaseUnit\", fields: [purchaseUnitId], references: [id], onDelete: SetNull)\n  salePrice      Decimal          @default(0)\n  costPrice      Decimal          @default(0)\n  stockQty       Decimal          @default(0)\n  minStock       Decimal          @default(0)\n  isActive       Boolean          @default(true)\n  createdAt      DateTime         @default(now())\n  updatedAt      DateTime         @updatedAt\n\n  images            ProductImage[]\n  conversions       ProductUnitConversion[]\n  tierPrices        ProductTierPrice[]\n  batches           StockBatch[]\n  purchaseLines     PurchaseLine[]\n  returnLines       SupplierReturnLine[]\n  transferLines     TransferLine[]\n  countLines        StockCountLine[]\n  lossLines         StockLoss[]\n  saleLines         SaleLine[]\n  threePackItems    ThreePackItem[]\n  clientReturnLines ClientReturnLine[]\n\n  @@index([companyId, name])\n  @@index([companyId, barcode])\n  @@index([companyId, reference])\n  @@map(\"products\")\n}\n\n/// Swipe gallery: ordered image list per product.\nmodel ProductImage {\n  id        String   @id @default(cuid())\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  url       String\n  sortOrder Int      @default(0)\n  createdAt DateTime @default(now())\n\n  @@index([productId, sortOrder])\n  @@map(\"product_images\")\n}\n\n/// 1 unit = factor × product base unit (e.g. 1 carton = 12 pièces).\nmodel ProductUnitConversion {\n  id        String   @id @default(cuid())\n  productId String\n  product   Product  @relation(fields: [productId], references: [id], onDelete: Cascade)\n  unitId    String\n  unit      Unit     @relation(fields: [unitId], references: [id], onDelete: Cascade)\n  factor    Decimal\n  /// Pack barcode: scanning it finds the product (sold in this pack unit).\n  barcode   String?\n  createdAt DateTime @default(now())\n\n  @@unique([productId, unitId])\n  @@index([barcode])\n  @@map(\"product_unit_conversions\")\n}\n\n/// Sale price per tier (détail / gros / super gros — customizable).\nmodel ProductTierPrice {\n  id        String    @id @default(cuid())\n  productId String\n  product   Product   @relation(fields: [productId], references: [id], onDelete: Cascade)\n  tierId    String\n  tier      PriceTier @relation(fields: [tierId], references: [id], onDelete: Cascade)\n  price     Decimal\n  updatedAt DateTime  @updatedAt\n\n  @@unique([productId, tierId])\n  @@map(\"product_tier_prices\")\n}\n\n// ─── Sales ───────────────────────────────────────────────────────────────────\n\n/// ORDER = bon de commande (no stock move) → DELIVERY (stock out) → INVOICE.\n/// TICKET = immediate van/POS cash sale (delivered + paid at once).\nmodel Sale {\n  id          String     @id @default(cuid())\n  companyId   String\n  company     Company    @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId    String?\n  kind        String\n  status      String     @default(\"DRAFT\")\n  channel     String     @default(\"DEPOT\")\n  number      String\n  clientId    String?\n  client      Customer?  @relation(fields: [clientId], references: [id], onDelete: SetNull)\n  locationId  String?\n  location    Store?     @relation(fields: [locationId], references: [id], onDelete: SetNull)\n  tierId      String?\n  tier        PriceTier? @relation(fields: [tierId], references: [id], onDelete: SetNull)\n  /// Staff member who created the doc (vendeur order, van ticket). Null = back-office/legacy.\n  createdById String?\n  createdBy   User?      @relation(\"CreatedSales\", fields: [createdById], references: [id], onDelete: SetNull)\n  tourneeId   String?\n  tournee     Tournee?   @relation(fields: [tourneeId], references: [id], onDelete: SetNull)\n  /// Source doc in the chain (delivery ← order, invoice ← delivery).\n  sourceId    String?\n  source      Sale?      @relation(\"SaleChain\", fields: [sourceId], references: [id], onDelete: SetNull)\n  children    Sale[]     @relation(\"SaleChain\")\n  remise      Decimal    @default(0)\n  total       Decimal    @default(0)\n  /// Cash received at sale time (versement link in Phase 6).\n  paid        Decimal    @default(0)\n  /// Van sale without QR scan while strict mode off.\n  offList     Boolean    @default(false)\n  qrScanned   Boolean    @default(false)\n  /// Order placed by the client through the portal (staff validates).\n  isPortal    Boolean    @default(false)\n  /// Silent sale-site check (van tickets): GPS captured on the phone at\n  /// sale time + distance to the client's registered position, for the\n  /// admin only. Null = no fix (denied/offline) or client has no position.\n  saleLat     Float?\n  saleLng     Float?\n  saleDistM   Float?\n  /// Van tickets: null = ON HOLD (driver may edit / delete it), set = CONFIRMED (final,\n  /// only an admin can edit or cancel it).\n  confirmedAt DateTime?\n  notes       String?\n  date        DateTime   @default(now())\n  createdAt   DateTime   @default(now())\n  updatedAt   DateTime   @updatedAt\n\n  lines   SaleLine[]\n  returns ClientReturn[]\n\n  /// Offline idempotency key: the sync opId that created this document.\n  /// Unique per company → an offline sale can never be double-applied.\n  opId String?\n\n  @@unique([companyId, kind, number])\n  @@unique([companyId, opId])\n  @@index([companyId, clientId])\n  @@index([companyId, status])\n  @@map(\"sales\")\n}\n\nmodel SaleLine {\n  id          String  @id @default(cuid())\n  saleId      String\n  sale        Sale    @relation(fields: [saleId], references: [id], onDelete: Cascade)\n  productId   String\n  product     Product @relation(fields: [productId], references: [id], onDelete: Restrict)\n  unitId      String?\n  qty         Decimal\n  baseQty     Decimal\n  unitPrice   Decimal\n  remise      Decimal @default(0)\n  lineTotal   Decimal\n  /// Snapshot COGS at delivery (for margin reports).\n  unitCost    Decimal @default(0)\n  /// 3pack gift line (price 0, stock still deducted).\n  isBonus     Boolean @default(false)\n  bonusRuleId String?\n\n  @@index([saleId])\n  @@map(\"sale_lines\")\n}\n\n/// Client returns: restock + refund (cash) or debt credit.\n\nmodel ClientReturn {\n  id         String   @id @default(cuid())\n  companyId  String\n  company    Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId   String?\n  clientId   String\n  client     Customer @relation(fields: [clientId], references: [id], onDelete: Restrict)\n  saleId     String?\n  sale       Sale?    @relation(fields: [saleId], references: [id], onDelete: SetNull)\n  locationId String\n  location   Store    @relation(fields: [locationId], references: [id], onDelete: Restrict)\n  number     String\n  refundType String\n  total      Decimal  @default(0)\n  notes      String?\n  date       DateTime @default(now())\n  createdAt  DateTime @default(now())\n\n  lines ClientReturnLine[]\n\n  /// Offline idempotency key: the sync opId that created this return.\n  opId String?\n\n  @@unique([companyId, number])\n  @@unique([companyId, opId])\n  @@index([companyId, clientId])\n  @@map(\"client_returns\")\n}\n\nmodel ClientReturnLine {\n  id        String       @id @default(cuid())\n  returnId  String\n  ret       ClientReturn @relation(fields: [returnId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product      @relation(fields: [productId], references: [id], onDelete: Restrict)\n  baseQty   Decimal\n  unitPrice Decimal\n  lineTotal Decimal\n\n  @@index([returnId])\n  @@map(\"client_return_lines\")\n}\n\n// ─── Tournées ────────────────────────────────────────────────────────────────\n\n/// Daily van visit list (admin-planned, vendeur-executed, optimized en route).\nmodel Tournee {\n  id          String       @id @default(cuid())\n  companyId   String\n  company     Company      @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  date        DateTime\n  locationId  String\n  location    Store        @relation(fields: [locationId], references: [id], onDelete: Restrict)\n  secteurId   String?\n  secteur     Secteur?     @relation(fields: [secteurId], references: [id], onDelete: SetNull)\n  status      String       @default(\"OPEN\")\n  notes       String?\n  /// Day tracking set by the livreur/vendeur: départ → fin de journée.\n  startedAt   DateTime?\n  finishedAt  DateTime?\n  /// GPS position captured at each stamp (best-effort, null when denied).\n  startedLat  Float?\n  startedLng  Float?\n  finishedLat Float?\n  finishedLng Float?\n  /// Auto-close: started but never finished the same day — the system ends\n  /// it at day end and flags it to the admin (driver didn't end journée).\n  autoClosed  Boolean      @default(false)\n  /// The recurring plan this day's tour was generated from (null = one-off).\n  planId      String?\n  plan        TourneePlan? @relation(fields: [planId], references: [id], onDelete: SetNull)\n  /// Order inside the day: a van can run up to two tours per day (0, 1).\n  slot        Int          @default(0)\n  createdAt   DateTime     @default(now())\n\n  stops TourneeStop[]\n  sales Sale[]\n\n  @@unique([planId, date])\n  @@index([companyId, date])\n  @@index([companyId, locationId])\n  @@index([locationId, date])\n  @@map(\"tournees\")\n}\n\nmodel TourneeStop {\n  id        String   @id @default(cuid())\n  tourneeId String\n  tournee   Tournee  @relation(fields: [tourneeId], references: [id], onDelete: Cascade)\n  clientId  String\n  client    Customer @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  position  Int      @default(0)\n  visited   Boolean  @default(false)\n  sold      Boolean  @default(false)\n  skipped   Boolean  @default(false)\n  total     Decimal  @default(0)\n\n  @@unique([tourneeId, clientId])\n  @@map(\"tournee_stops\")\n}\n\n// ─── Desktop licensing (server side — self-hosted, single business) ─────────\n\n/// Known machines (informational registration from the desktop app).\n/// status drives the poll: pending | activated | revoked. A machine row is\n/// the server-side counterpart of the client's .lic files.\nmodel Machine {\n  id                  String    @id @default(cuid())\n  machineId           String    @unique\n  label               String?\n  phone               String?\n  specs               Json?\n  status              String    @default(\"pending\")\n  token               String?\n  activationKey       String?\n  activationType      String    @default(\"machine\")\n  consumedByMachineId String?\n  trialStart          DateTime?\n  trialEnd            DateTime?\n  activatedAt         DateTime?\n  contactName         String?\n  city                String?\n  workshop            String?\n  email               String?\n  deviceSpecs         Json?\n  trialIp             String?\n  lastIp              String?\n  lastSeen            DateTime  @default(now())\n  createdAt           DateTime  @default(now())\n\n  subscription MachineSubscription?\n\n  @@index([status, createdAt])\n  @@map(\"machines\")\n}\n\n/// Billing posture per machine (manual for now — no payment provider).\n/// expiry/suspension flips the same lock path as a manual revoke.\nmodel MachineSubscription {\n  id          String    @id @default(cuid())\n  machineId   String    @unique\n  machine     Machine   @relation(fields: [machineId], references: [machineId], onDelete: Cascade)\n  plan        String    @default(\"standard\")\n  status      String    @default(\"trial\")\n  expiresAt   DateTime?\n  graceEndsAt DateTime?\n  activatedBy String?\n  notes       String?\n  createdAt   DateTime  @default(now())\n  updatedAt   DateTime  @updatedAt\n\n  @@map(\"machine_subscriptions\")\n}\n\n/// Manually blocked IPs (abuse control). Blocks register/trial only —\n/// never breaks an already-entitled install.\nmodel BlockedIp {\n  ip        String   @id\n  reason    String?\n  createdAt DateTime @default(now())\n\n  @@map(\"blocked_ips\")\n}\n\n/// Human-readable activation keys (DILI-XXXX-XXXX-XXXX). Pool keys bind to\n/// the first machine that redeems them; revoked keys kill the install.\nmodel LicenseKey {\n  id                  String   @id @default(cuid())\n  machineId           String?\n  label               String?\n  humanKey            String   @unique\n  revoked             Boolean  @default(false)\n  /// Pool key consumed by another machine (resetKey restores it).\n  consumedByMachineId String?\n  createdAt           DateTime @default(now())\n  updatedAt           DateTime @updatedAt\n\n  @@map(\"license_keys\")\n}\n\n/// One trial per machine.\nmodel TrialIssue {\n  machineId String   @id\n  start     DateTime\n  end       DateTime\n  createdAt DateTime @default(now())\n\n  @@map(\"trial_issues\")\n}\n\n/// Vendor-side tunnel slots: one public hostname per client\n/// (client1, client2…) pointing at the CLIENT's own PC via an outbound\n/// connector (Cloudflare Tunnel). The vendor provisions the hostname +\n/// credentials; client data never touches the vendor server, so a vendor\n/// outage never stops a client (LAN + offline keep working).\nmodel TunnelSlot {\n  id              String   @id @default(cuid())\n  subdomain       String   @unique\n  domain          String\n  label           String?\n  status          String   @default(\"pending\")\n  tunnelId        String?\n  /// Connector token for the client's PC (shown once, admin-only).\n  token           String?\n  clientMachineId String?\n  notes           String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  deployments ClientDeployment[]\n\n  @@map(\"tunnel_slots\")\n}\n\n/// Vendor-side client deployments: one row per sold client version. The\n/// worker (scripts/provision-worker) picks up `pending` rows and builds the\n/// server side automatically: subdomain + port + database + nginx vhost +\n/// tunnel pairing, then flips the row to `active` (or `failed`).\n/// Domain rules (owner decisions, enforced below + in the API):\n/// - `domain` (the FIRST/baked domain) is vendor-only: never returned to the\n///   client, never editable, never deletable — the row itself has no DELETE\n///   endpoint, only activate/deactivate.\n/// - The client may set ONE override domain with their activation code only\n///   (`domainOverride`); flipping `overrideActive` chooses which one serves.\nmodel ClientDeployment {\n  id             String      @id @default(cuid())\n  client         String      @unique\n  version        String\n  domain         String\n  domainOverride String?\n  overrideActive Boolean     @default(false)\n  /// Shop PC bound to this deployment (activation-code changes resolve here).\n  machineId      String?\n  tunnelSlotId   String?\n  tunnelSlot     TunnelSlot? @relation(fields: [tunnelSlotId], references: [id], onDelete: SetNull)\n  /// pending → provisioning | active | failed | deactivated\n  status         String      @default(\"pending\")\n  lastError      String?\n  notes          String?\n  createdAt      DateTime    @default(now())\n  updatedAt      DateTime    @updatedAt\n\n  @@map(\"client_deployments\")\n}\n\n// ─── Mobile sync ─────────────────────────────────────────────────────────────\n\n/// One APK device, optionally locked to a van (vanBindingMode = LOCKED).\nmodel Device {\n  id         String    @id @default(cuid())\n  companyId  String\n  company    Company   @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  label      String\n  locationId String?\n  location   Store?    @relation(fields: [locationId], references: [id], onDelete: SetNull)\n  userId     String?\n  user       User?     @relation(fields: [userId], references: [id], onDelete: SetNull)\n  tokenHash  String    @unique\n  lastSyncAt DateTime?\n  isActive   Boolean   @default(true)\n  createdAt  DateTime  @default(now())\n\n  ops SyncOp[]\n\n  @@index([companyId])\n  @@map(\"devices\")\n}\n\n/// Idempotent offline operation log (opId unique per company).\n/// Failed ops stay visible for owner reconciliation.\nmodel SyncOp {\n  id         String    @id @default(cuid())\n  companyId  String\n  company    Company   @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  deviceId   String?\n  device     Device?   @relation(fields: [deviceId], references: [id], onDelete: SetNull)\n  opId       String\n  kind       String\n  status     String\n  error      String?\n  /// Created document id (sale/transfer/payment…) for reconciliation.\n  resultId   String?\n  /// Real action time on the phone (op envelope `occurredAt`), not sync time.\n  occurredAt DateTime?\n  createdAt  DateTime  @default(now())\n\n  @@unique([companyId, opId])\n  @@index([companyId, deviceId])\n  @@map(\"sync_ops\")\n}\n\n// ─── Purchases ───────────────────────────────────────────────────────────────\n\nmodel PurchaseInvoice {\n  id              String   @id @default(cuid())\n  companyId       String\n  company         Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId        String?\n  supplierId      String\n  supplier        Supplier @relation(fields: [supplierId], references: [id], onDelete: Restrict)\n  number          String\n  date            DateTime @default(now())\n  /// Invoice-level remise (amount). Line remises live on lines.\n  remise          Decimal  @default(0)\n  total           Decimal  @default(0)\n  /// Paid so far via invoice payments (versements linked below).\n  paid            Decimal  @default(0)\n  notes           String?\n  /// Optional photo of the supplier's paper invoice (stored as WebP).\n  invoiceImageUrl String?\n  createdAt       DateTime @default(now())\n  updatedAt       DateTime @updatedAt\n\n  lines    PurchaseLine[]\n  returns  SupplierReturn[]\n  payments Versement[]      @relation(\"InvoicePayments\")\n\n  @@unique([companyId, number])\n  @@index([companyId, supplierId])\n  @@map(\"purchase_invoices\")\n}\n\nmodel PurchaseLine {\n  id         String          @id @default(cuid())\n  invoiceId  String\n  invoice    PurchaseInvoice @relation(fields: [invoiceId], references: [id], onDelete: Cascade)\n  productId  String\n  product    Product         @relation(fields: [productId], references: [id], onDelete: Restrict)\n  unitId     String?\n  /// Qty in line unit + free units (supplier gifts).\n  qty        Decimal\n  freeQty    Decimal         @default(0)\n  /// Qty converted to product base unit (qty + freeQty) × factor.\n  baseQty    Decimal\n  unitPrice  Decimal\n  remise     Decimal         @default(0)\n  lineTotal  Decimal\n  expiryDate DateTime?\n  batchId    String?         @unique\n  batch      StockBatch?     @relation(fields: [batchId], references: [id], onDelete: SetNull)\n\n  @@index([invoiceId])\n  @@map(\"purchase_lines\")\n}\n\n/// FIFO/FEFO stock batches created at purchase (consumed by sales in Phase 5).\nmodel StockBatch {\n  id         String    @id @default(cuid())\n  companyId  String\n  company    Company   @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  productId  String\n  product    Product   @relation(fields: [productId], references: [id], onDelete: Cascade)\n  /// Null = main stock (Phase 4 backfills to the main depot).\n  storeId    String?\n  location   Store?    @relation(fields: [storeId], references: [id], onDelete: SetNull)\n  /// Set while in-transit (declare→confirm holding).\n  transferId String?\n  transfer   Transfer? @relation(\"HoldingBatches\", fields: [transferId], references: [id], onDelete: SetNull)\n  qty        Decimal\n  initialQty Decimal\n  unitCost   Decimal\n  expiryDate DateTime?\n  createdAt  DateTime  @default(now())\n\n  purchaseLine PurchaseLine?\n\n  @@index([companyId, productId])\n  @@index([productId, expiryDate])\n  @@map(\"stock_batches\")\n}\n\n/// Returns to supplier: restock reversal + supplier credit note (balance down).\nmodel SupplierReturn {\n  id         String           @id @default(cuid())\n  companyId  String\n  company    Company          @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId   String?\n  supplierId String\n  supplier   Supplier         @relation(fields: [supplierId], references: [id], onDelete: Restrict)\n  invoiceId  String?\n  invoice    PurchaseInvoice? @relation(fields: [invoiceId], references: [id], onDelete: SetNull)\n  number     String\n  date       DateTime         @default(now())\n  total      Decimal          @default(0)\n  notes      String?\n  createdAt  DateTime         @default(now())\n\n  lines SupplierReturnLine[]\n\n  @@unique([companyId, number])\n  @@index([companyId, supplierId])\n  @@map(\"supplier_returns\")\n}\n\nmodel SupplierReturnLine {\n  id        String         @id @default(cuid())\n  returnId  String\n  ret       SupplierReturn @relation(fields: [returnId], references: [id], onDelete: Cascade)\n  productId String\n  product   Product        @relation(fields: [productId], references: [id], onDelete: Restrict)\n  baseQty   Decimal\n  unitPrice Decimal\n  lineTotal Decimal\n\n  @@index([returnId])\n  @@map(\"supplier_return_lines\")\n}\n\nmodel Expense {\n  id          String       @id @default(cuid())\n  companyId   String\n  company     Company      @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId    String?\n  typeId      String?\n  type        ExpenseType? @relation(fields: [typeId], references: [id], onDelete: SetNull)\n  /// Optional van link (fuel / maintenance per van).\n  locationId  String?\n  location    Store?       @relation(fields: [locationId], references: [id], onDelete: SetNull)\n  label       String\n  description String?\n  amount      Decimal\n  expenseDate DateTime     @default(now())\n  createdAt   DateTime     @default(now())\n  deletedAt   DateTime?\n\n  /// Offline idempotency key: the sync opId that created this expense.\n  opId String?\n\n  @@unique([companyId, opId])\n  @@index([companyId, expenseDate])\n  @@index([companyId, typeId])\n  @@map(\"expenses\")\n}\n\n// ─── Cash ────────────────────────────────────────────────────────────────────\n\n/// Cash-only money movements (per plan). Client/supplier payments move balances;\n/// CASH_COLLECTION records van→depot handovers (auto-created on transfer confirm).\nmodel Versement {\n  id                String           @id @default(cuid())\n  companyId         String\n  company           Company          @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId          String?\n  kind              String\n  clientId          String?\n  client            Customer?        @relation(fields: [clientId], references: [id], onDelete: SetNull)\n  supplierId        String?\n  supplier          Supplier?        @relation(fields: [supplierId], references: [id], onDelete: SetNull)\n  transferId        String?\n  transfer          Transfer?        @relation(fields: [transferId], references: [id], onDelete: SetNull)\n  purchaseInvoiceId String?\n  purchaseInvoice   PurchaseInvoice? @relation(\"InvoicePayments\", fields: [purchaseInvoiceId], references: [id], onDelete: SetNull)\n  /// Van/day attribution (till reconciliation): set when the money moves on\n  /// a van — client payment collected on tour, or handover to the depot.\n  /// Plain scalars (no FK): history must survive van/tournee cleanup.\n  locationId        String?\n  tourneeId         String?\n  amount            Decimal\n  date              DateTime         @default(now())\n  notes             String?\n  createdAt         DateTime         @default(now())\n\n  /// Offline idempotency key: the sync opId that created this payment.\n  opId String?\n\n  @@unique([companyId, opId])\n  @@index([companyId, date])\n  @@index([companyId, clientId])\n  @@index([companyId, supplierId])\n  @@index([companyId, locationId, date])\n  @@map(\"versements\")\n}\n\n/// Daily van-till close (صندوق اليوم): expected vs collected vs remitted.\n/// OPEN = computed live, nothing stored. DECLARED = livreur counted and\n/// submitted his till (pending admin). CLOSED = admin snapshotted + locked.\n\nmodel DailyClose {\n  id             String    @id @default(cuid())\n  companyId      String\n  company        Company   @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId       String?\n  vanId          String\n  van            Store     @relation(fields: [vanId], references: [id], onDelete: Cascade)\n  /// Day at midnight (local). Unique per van-day.\n  date           DateTime\n  /// Snapshot taken at close (live-computed while open/declared).\n  expected       Decimal   @default(0)\n  collected      Decimal   @default(0)\n  clientPayments Decimal   @default(0)\n  expenses       Decimal   @default(0)\n  returnsCash    Decimal   @default(0)\n  dueTotal       Decimal   @default(0)\n  /// Livreur-counted till, submitted for control.\n  declared       Decimal?\n  declaredById   String?\n  declaredAt     DateTime?\n  /// Accepted handover (CASH_COLLECTION versements).\n  remitted       Decimal   @default(0)\n  /// remitted − (collected + clientPayments − expenses − returnsCash).\n  difference     Decimal   @default(0)\n  status         String    @default(\"DECLARED\")\n  closedById     String?\n  closedAt       DateTime?\n  notes          String?\n\n  @@unique([companyId, vanId, date])\n  @@index([companyId, date])\n  @@map(\"daily_closes\")\n}\n\n/// Client advances (toggle-gated, default OFF). Credits the client balance.\nmodel Deposit {\n  id        String   @id @default(cuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  seasonId  String?\n  clientId  String\n  client    Customer @relation(fields: [clientId], references: [id], onDelete: Restrict)\n  amount    Decimal\n  date      DateTime @default(now())\n  notes     String?\n  createdAt DateTime @default(now())\n\n  @@index([companyId, clientId])\n  @@map(\"deposits\")\n}\n\nmodel DocumentSequence {\n  id        String  @id @default(cuid())\n  companyId String\n  storeId   String?\n  type      String\n  year      Int\n  nextNo    Int     @default(1)\n\n  @@unique([companyId, storeId, type, year])\n  @@map(\"document_sequences\")\n}\n\n/// Per-user distance/time snapshot to every geolocated client.\n/// Written on each \"actualiser\" (and manual entry); read back on open.\nmodel ClientDistance {\n  id        String   @id @default(cuid())\n  companyId String\n  company   Company  @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  userId    String\n  user      User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  clientId  String\n  client    Customer @relation(fields: [clientId], references: [id], onDelete: Cascade)\n  distanceM Float\n  durationS Float\n  atLat     Float\n  atLng     Float\n  /// \"osrm\" (road) or \"estimate\" (straight-line fallback).\n  source    String   @default(\"estimate\")\n  updatedAt DateTime @updatedAt\n\n  @@unique([companyId, userId, clientId])\n  @@index([companyId, userId])\n  @@map(\"client_distances\")\n}\n\n// ─── 3pack: free-colis bonus rules ───────────────────────────────────────────\n\n/// SINGLE: buy X colis of P → Y colis of P free.\n/// PACK: buy A×a + B×b (+ …) → fixed free colis. Every multiple counts.\n/// Rules are deactivated, never hard-deleted (offline sales reference them).\nmodel ThreePackRule {\n  id         String          @id @default(cuid())\n  companyId  String\n  company    Company         @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  name       String\n  mode       String\n  isActive   Boolean         @default(true)\n  /// Editing a rule's products/quantities archives it and creates a new rule,\n  /// so an offline sale always validates against the exact rule the phone had.\n  isArchived Boolean         @default(false)\n  /// Promotion window (inclusive, whole days). Null = open-ended. Past endsAt the\n  /// rule is switched off automatically; before startsAt it does not apply yet.\n  startsAt   DateTime?\n  endsAt     DateTime?\n  /// PERCENT rules: the % taken off every target product's line.\n  percent    Decimal?\n  createdAt  DateTime        @default(now())\n  items      ThreePackItem[]\n\n  @@index([companyId])\n  @@map(\"three_pack_rules\")\n}\n\nmodel ThreePackItem {\n  id        String        @id @default(cuid())\n  ruleId    String\n  rule      ThreePackRule @relation(fields: [ruleId], references: [id], onDelete: Cascade)\n  role      String\n  productId String\n  product   Product       @relation(fields: [productId], references: [id], onDelete: Restrict)\n  /// Quantity in colis.\n  colis     Decimal\n  /// PRICE rules, GIVE (target) items: the new price per colis.\n  price     Decimal?\n\n  @@index([ruleId])\n  @@index([productId])\n  @@map(\"three_pack_items\")\n}\n\n/// \"Client closed\" report from a van phone: the driver reached the client's\n/// shop, found it shut and photographed it (one or several photos). Created\n/// offline on the phone, synced later; idempotent by opId.\nmodel ClosedVisit {\n  id         String             @id @default(cuid())\n  companyId  String\n  company    Company            @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  customerId String\n  customer   Customer           @relation(fields: [customerId], references: [id], onDelete: Cascade)\n  /// The van the driver was on.\n  locationId String?\n  location   Store?             @relation(fields: [locationId], references: [id], onDelete: SetNull)\n  userId     String?\n  user       User?              @relation(fields: [userId], references: [id], onDelete: SetNull)\n  opId       String?\n  note       String?\n  /// Where the phone was when the photo was taken.\n  lat        Float?\n  lng        Float?\n  /// Real action time on the phone (not the sync time).\n  occurredAt DateTime\n  createdAt  DateTime           @default(now())\n  photos     ClosedVisitPhoto[]\n\n  @@unique([companyId, opId])\n  @@index([companyId, occurredAt])\n  @@index([customerId])\n  @@map(\"closed_visits\")\n}\n\nmodel ClosedVisitPhoto {\n  id        String      @id @default(cuid())\n  visitId   String\n  visit     ClosedVisit @relation(fields: [visitId], references: [id], onDelete: Cascade)\n  url       String\n  sortOrder Int         @default(0)\n\n  @@index([visitId])\n  @@map(\"closed_visit_photos\")\n}\n\n/// Recurring tour: one van + one weekday + one sector, every week or every 2\n/// weeks, with no end date. The daily Tournee rows (stamps, stops, sales) are\n/// generated from it on demand. A van+weekday \"cell\" holds up to two plans.\nmodel TourneePlan {\n  id            String    @id @default(cuid())\n  companyId     String\n  company       Company   @relation(fields: [companyId], references: [id], onDelete: Cascade)\n  locationId    String\n  location      Store     @relation(fields: [locationId], references: [id], onDelete: Cascade)\n  secteurId     String?\n  secteur       Secteur?  @relation(fields: [secteurId], references: [id], onDelete: SetNull)\n  /// 0 = Sunday … 6 = Saturday (Algiers calendar).\n  weekday       Int\n  /// 1 = every week, 2 = every 2 weeks.\n  intervalWeeks Int       @default(1)\n  /// First occurrence, \"YYYY-MM-DD\". Biweekly weeks are counted from here.\n  anchorKey     String\n  /// Slot inside the van+weekday cell (0 or 1).\n  slot          Int       @default(0)\n  /// Hand-picked ordered client ids (JSON array). Null = every active client\n  /// of the sector, always up to date.\n  clientIds     String?\n  /// Single dates removed from the plan (\"YYYY-MM-DD,YYYY-MM-DD\") — never recreated.\n  skips         String    @default(\"\")\n  notes         String?\n  isActive      Boolean   @default(true)\n  createdAt     DateTime  @default(now())\n  tournees      Tournee[]\n\n  @@index([companyId, isActive])\n  @@index([locationId, weekday])\n  @@map(\"tournee_plans\")\n}\n"
}

